{"function": "Offering to go", "situation": "Offering to go somewhere for someone", "cue": "Offer to go to the store for your friend.", "text": "店へ行くよ", "english": "I'll go to the store.", "speaker": "either"},
{"function": "Stating intention", "situation": "Stating your plan to go somewhere", "cue": "Tell your friend you are going to the station.", "text": "駅へ行くんだ", "english": "I'm going to the station.", "speaker": "either"},
{"function": "Asking for confirmation", "situation": "Asking if someone is going somewhere", "cue": "Ask your friend if they are going to the movie.", "text": "映画へ行く？", "english": "Are you going to the movie?", "speaker": "either"},
{"function": "Describing past action", "situation": "Describing where you went yesterday", "cue": "Tell your friend you went to your friend's house yesterday.", "text": "昨日、友達の家へ行ったんだ", "english": "Yesterday, I went to my friend's house.", "speaker": "either"},
{"function": "Describing future action", "situation": "Describing where you will go tomorrow", "cue": "Tell your friend you will go to the park tomorrow.", "text": "明日、公園へ行くよ", "english": "I'll go to the park tomorrow.", "speaker": "either"}
]}

