{"function": "Asking", "situation": "Asking about a drink", "cue": "Ask your friend what they want to drink.", "text": "何飲む？", "english": "What will you drink?", "speaker": "either"},
{"function": "Answering", "situation": "Answering a question about drinking", "cue": "Tell your friend you want to drink water.", "text": "水飲みたい。", "english": "I want to drink water.", "speaker": "either"},
