{
  "items": [
    {
      "n": 1,
      "reading": "ここかあそこかどっちにする？",
      "romaji": "Koko ka asoko ka docchi ni suru?"
    },
    {
      "n": 2,
      "reading": "えいがはどっちがみたい？",
      "romaji": "Eiga wa docchi ga mitai?"
    },
    {
      "n": 3,
      "reading": "どっちからいくのがいい？",
      "romaji": "Docchi kara iku no ga ii?"
    },
    {
      "n": 4,
      "reading": "うん、またほんをかうよ",
      "romaji": "Un, mata hon o kau yo"
    },
    {
      "n": 5,
      "reading": "あしたまたくる",
      "romaji": "Ashita mata kuru"
    },
    {
      "n": 6,
      "reading": "きょうまたいそがしいんだ。",
      "romaji": "Kyou mata isogashii n da."
    },
    {
      "n": 7,
      "reading": "ほんはあそこにあるよ。",
      "romaji": "Hon wa asoko ni aru yo."
    },
    {
      "n": 8,
      "reading": "えきはあそこ？",
      "romaji": "Eki wa asoko?"
    },
    {
      "n": 9,
      "reading": "じゃあ、あそこで会おうよ。",
      "romaji": "Jaa, asoko de aou yo."
    },
    {
      "n": 10,
      "reading": "あれはどこ？",
      "romaji": "Are wa doko?"
    },
    {
      "n": 11,
      "reading": "あれ、どうおもう？",
      "romaji": "Are, dou omou?"
    },
    {
      "n": 12,
      "reading": "これとあれ、どっち？",
      "romaji": "Kore to are, docchi?"
    },
    {
      "n": 13,
      "reading": "あ、ごめん！だいじょうぶ？",
      "romaji": "A, gomen! Daijoubu?"
    },
    {
      "n": 14,
      "reading": "ごめん、きょうはもうかえるね。",
      "romaji": "Gomen, kyou wa mou kaeru ne."
    },
    {
      "n": 15,
      "reading": "ごめん、おそかった。",
      "romaji": "Gomen, osokatta."
    },
    {
      "n": 16,
      "reading": "いまでんわしてる？",
      "romaji": "Ima denwa shiteru?"
    },
    {
      "n": 17,
      "reading": "またでんわするね。",
      "romaji": "Mata denwa suru ne."
    },
    {
      "n": 18,
      "reading": "でんわしないといけない。",
      "romaji": "Denwa shinai to ikenai."
    },
    {
      "n": 19,
      "reading": "うん、いこう。",
      "romaji": "Un, ikou."
    },
    {
      "n": 20,
      "reading": "うん、わかるよ。",
      "romaji": "Un, wakaru yo."
    },
    {
      "n": 21,
      "reading": "うん、あるよ。",
      "romaji": "Un, aru yo."
    },
    {
      "n": 22,
      "reading": "いいえ、きょうえきへいきません。",
      "romaji": "Iie, kyou eki e ikimasen."
    },
    {
      "n": 23,
      "reading": "いいえ、すみません、きょうはいそがしいです。",
      "romaji": "Iie, sumimasen, kyou wa isogashii desu."
    },
    {
      "n": 24,
      "reading": "いいえ、そのひとはしりません。",
      "romaji": "Iie, sono hito wa shirimasen."
    },
    {
      "n": 25,
      "reading": "たぶんいえでえいがをみる",
      "romaji": "Tabun ie de eiga o miru"
    },
    {
      "n": 26,
      "reading": "あのあたらしいみせ、たぶんおいしいよ",
      "romaji": "Ano atarashii mise, tabun oishii yo"
    },
    {
      "n": 27,
      "reading": "ごめん、そのほんはたぶんもうない",
      "romaji": "Gomen, sono hon wa tabun mou nai"
    },
    {
      "n": 28,
      "reading": "でんしゃにのろうか。",
      "romaji": "Densha ni norou ka."
    },
    {
      "n": 29,
      "reading": "きのうバスにのった？",
      "romaji": "Kinou basu ni notta?"
    },
    {
      "n": 30,
      "reading": "いまでんしゃにのる。",
      "romaji": "Ima densha ni noru."
    }
  ]
}

